import sys

def read_input():
    import sys
    data = sys.stdin.read().split()
    t = int(data[0])
    n = int(data[1])
    queries = [(int(data[i * 2 + 2]), int(data[i * 2 + 3])) for i in range(t)]
    return n, queries

def doe_graph_path_length(n, a, b):
    if a > b:
        a, b = b, a
    if n == 1:
        return 1
    sizes = [1, 2]
    for i in range(2, n + 1):
        sizes.append(sizes[-1] + sizes[-2])

    def find_in_subgraph(a, b, n):
        if n == 0:
            return 0
        if n == 1:
            return 1
        size_n_minus_1 = sizes[n - 1]
        if b <= size_n_minus_1:
            return find_in_subgraph(a, b, n - 1)
        elif a > size_n_minus_1:
            return find_in_subgraph(a - size_n_minus_1, b - size_n_minus_1, n - 2) + sizes[n - 2]
        else:
            return min(b - a, a + sizes[n - 2] - b + 2)

    return find_in_subgraph(a, b, n)

def main():
    n, queries = read_input()
    for a, b in queries:
        print(doe_graph_path_length(n, a, b))

if __name__ == "__main__":
    main()
